  add('grammar','standard','「とても 長い 道。」の「とても」は、どの言葉をくわしくしていますか。','長い',['道','とても','ありません'],['「どれくらい」長いのかを説明しています。','「とても」のすぐあとの言葉に注目します。'],'「とても」は、「どれくらい」長いのかを説明して、「長い」をくわしくしています。',null,['ながい','長い']);
  add('grammar','standard','「だれが」「何が」にあたる言葉を、何といいますか。','主語',['述語','主題','目的'],['文の中で、「～は」「～が」の形になる言葉です。','「どうする」にあたる言葉は、述語といいます。'],'「だれが」「何が」にあたる言葉は「主語」、「どうする」「どんなだ」にあたる言葉は「述語」です。',null,['しゅご','主語']);
  add('grammar','standard','「雨がふったので、試合は中止になった。」で、理由を表している部分はどこですか。','雨がふったので',['試合は','中止になった','雨が'],['「なぜ」にあたる部分をさがします。','「ので」がついています。'],'「雨がふったので」が、試合が中止になった理由を表しています。');
  add('grammar','standard','次のうち、動きを表す言葉（動詞）はどれですか。','歩く',['美しい','学校','静かだ'],['「どうする」にあたる言葉をさがします。','ものの名前やようすを表す言葉ではありません。'],'「歩く」は動きを表す言葉（動詞）です。「美しい」「静かだ」はようすを表す言葉、「学校」はものの名前です。');
  add('grammar','standard','次のうち、「～だ」の形で終わる、ようすを表す言葉はどれですか。','静かだ',['歩く','学校','美しい'],['「だ」で言い切る形をさがします。','ようすを表す言葉です。'],'「静かだ」は、「だ」で終わる、ようすを表す言葉です。「美しい」は「い」で終わる、ようすを表す言葉です。');
  add('grammar','standard','「ぼくは 弟と 公園へ 行った。」の「弟と」は、何を表す言葉ですか。','いっしょに行った相手',['行った場所','行った時間','行った理由'],['「だれと」にあたる言葉です。','「と」がついています。'],'「弟と」は、「だれと」行ったかを表す言葉です。');
  add('grammar','standard','「兄の 作った ケーキは、とても おいしい。」の主語は何ですか。','ケーキは',['兄の','作った','おいしい'],['「何が」おいしいのでしょう。','主語は、「～は」「～が」の形で、くわしい言葉がつくこともあります。'],'この文では、「何が」にあたる「ケーキは」が主語です。「兄の作った」は、ケーキをくわしくしています。');
  add('grammar','standard','「ぼくが 昨日 公園で 見た 犬は、とても 大きかった。」の述語は何ですか。','大きかった',['見た','犬は','ぼくが'],['文の終わりにある言葉をさがします。','「犬は」どうだったのでしょう。'],'この文では、「犬は」に対応する「大きかった」が述語です。「見た」は、犬をくわしくする言葉です。');

  add('grammar','advanced','「ぼくの 弟は、いつも 元気に 走り回って いる。」の「いつも」は、どの言葉をくわしくしていますか。','走り回っている',['元気に','弟は','ぼくの'],['「いつ」にあたる言葉です。','動きを表す言葉をくわしくしています。'],'「いつも」は、「いつ」走り回っているのかを表して、「走り回っている」をくわしくしています。');
  add('grammar','advanced','「これは、わたしが 先生から いただいた 本です。」の述語は何ですか。','本です',['いただいた','わたしが','これは'],['文の終わりの言葉に注目します。','「これは」にあたる述語をさがします。'],'この文では、「これは」に対応する「本です」が述語です。「いただいた」は本をくわしくしています。');
  add('grammar','advanced','次のうち、主語が省略されている文はどれですか。','朝おきて、顔をあらった。',['ぼくは朝おきた。','雪がふった。','弟が顔をあらった。'],['「だれが」が書かれていない文をさがします。','ほかの文には、「ぼくは」「雪が」「弟が」がついています。'],'「朝おきて、顔をあらった。」には、「だれが」にあたる言葉がありません。');
  add('grammar','advanced','「雪がふり、風もふいた。」の「雪がふり」と「風もふいた」は、どんな関係ですか。','同じように、ならんでいる関係',['理由と結果の関係','反対の内容の関係','主語と述語の関係'],['二つの内容は、どちらも天気のようすです。','どちらかがもう一方の理由になっているでしょうか。'],'「雪がふり」と「風もふいた」は、同じようにならべられている関係です。');
  add('grammar','advanced','「雪がとけると、水になる。」の「と」は、どんなはたらきをしていますか。','「とければ、かならず水になる」という関係を表す',['場所を表す','いっしょにいる相手を表す','ならべて言う'],['「～すると、～になる」という形です。','前の動きがおきたとき、あとの動きがおこることを表します。'],'「と」は、「とけたら、かならず水になる」という関係を表しています。');
  add('grammar','advanced','次のうち、主語と述語が合っていない文はどれですか。','わたしの夢は、パイロットになりたい。',['わたしの夢は、パイロットになることです。','わたしは、パイロットになりたい。','雪は、白いです。'],['「夢は」に対応する終わり方を考えます。','「夢は～ことです」の形にすれば直せます。'],'「わたしの夢は、パイロットになりたい。」は、主語の「夢は」と述語の「なりたい」が合っていません。「～になることです」と直します。');
  add('grammar','advanced','「ぼくは大きな白い犬を見た。」の「大きな」と「白い」は、どの言葉をくわしくしていますか。','犬を',['見た','ぼくは','白い'],['二つとも、「どんな」にあたる言葉です。','見たものは何でしょう。'],'「大きな」と「白い」は、どちらも「犬を」をくわしくしています。');
  add('grammar','advanced','次のうち、述語が「ようすを表す言葉」になっている文はどれですか。','雪は白い。',['雪がふる。','雪がとける。','雪がつもる。'],['「どんなだ」にあたる述語をさがします。','ほかの文は、「どうする」にあたる述語です。'],'「雪は白い。」の述語「白い」は、ようすを表す言葉です。ほかの文は、動きを表す述語です。');

  // ---- つなぎ言葉・指示語：基礎8・標準12・発展8 ----
  function cj(diff,sentence,answer,wrong,hints,explanation,inp){
    add('conjunction',diff,'□に入る言葉は何ですか。\n「'+sentence+'」',answer,wrong,hints,explanation,null,inp||null);
  }
  cj('basic','雪がふり始めた。□、道がだんだん白くなった。','すると',['しかし','または','なぜなら'],['前のことがおきたあとに、あとのことがおきています。','「そのとき」という意味の言葉をさがします。'],'「すると」は、前のことがおきたあとで、あとのことがおきるときに使います。',['すると']);
  cj('basic','雪は冷たい。□、とても重い。','しかも',['しかし','または','ところで'],['前の文に、さらに足しています。','「その上」という意味の言葉をさがします。'],'「しかも」は、前のことにさらに足して言うときに使います。',['しかも','そのうえ']);
  cj('basic','雪がふっていた。□、思ったよりあたたかかった。','けれども',['だから','そして','つまり'],['前の文と反対の内容になっています。','雪がふると、ふつうはどうでしょう。'],'「けれども」は、前の文と反対のことが続くときに使います。',['けれども','しかし','でも']);
  cj('basic','行き方は、電車□バスだ。','または',['そして','だから','しかし'],['どちらかをえらぶ言い方です。','「どちらか」という意味の言葉をさがします。'],'「または」は、どちらかをえらぶときに使います。',['または','あるいは']);
  cj('basic','遠足は中止になった。□、雪がたくさんふったからだ。','なぜなら',['だから','そして','または'],['あとの文が、理由になっています。','「どうしてかというと」という意味の言葉をさがします。'],'「なぜなら」は、前のことの理由を、あとで言うときに使います。',['なぜなら']);
  cj('basic','雪は、水がこおったものだ。□、水のなかまだ。','つまり',['しかし','または','ところで'],['前の文を、まとめたり言いかえたりしています。','「言いかえれば」という意味の言葉をさがします。'],'「つまり」は、前のことを言いかえたり、まとめたりするときに使います。',['つまり','すなわち']);
  add('conjunction','basic','相手の近くにあるものを、さして言うときの言葉は何ですか。','それ',['これ','あれ','どれ'],['こそあど言葉の中で「そ」で始まる言葉をさがします。','自分からは少しはなれていて、相手に近いものです。'],'相手に近いものは「それ」と言います。自分に近いものは「これ」、遠いものは「あれ」です。');
  add('conjunction','basic','ようすをたずねるときに使う言葉は何ですか。','どんな',['どこ','だれ','いつ'],['こそあど言葉の中で「ど」で始まる言葉をさがします。','「こんな」「そんな」「あんな」にあたる、たずねる言葉です。'],'ようすをたずねるときは「どんな」と言います。',null,['どんな']);

  cj('standard','雪かきが終わった。□、ごはんにしよう。','さて',['つまり','なぜなら','しかし'],['話を次のことにうつしています。','「ひと区切りついたので」という意味の言葉をさがします。'],'「さて」は、話を次のことにうつすときに使います。',['さて','では']);
  cj('standard','雪遊びは楽しかったね。□、宿題はもう終わった。','ところで',['だから','つまり','しかも'],['話題を変えています。','前の話とは、ちがうことを言い出しています。'],'「ところで」は、話題を変えるときに使います。',['ところで','それはそうと']);
  cj('standard','雪にはいろいろな形がある。□、六角形のけっしょうもある。','たとえば',['ところが','または','だから'],['あとの文が、前の文の具体的な例になっています。','「例をあげると」という意味の言葉をさがします。'],'「たとえば」は、前に言ったことの例をあげるときに使います。',['たとえば']);
  cj('standard','雪の山で遊んでもよい。□、くらくなる前に帰ること。','ただし',['つまり','しかも','たとえば'],['前の文に、条件を足しています。','「ただし書き」のときに使う言葉です。'],'「ただし」は、前に言ったことに、条件や例外を足すときに使います。',['ただし']);
  cj('standard','雪が深い。□、風もつよい。','そのうえ',['しかし','または','だから'],['前の文に、さらに足しています。','「さらに」という意味の言葉をさがします。'],'「そのうえ」は、前のことにさらに足して言うときに使います。',['そのうえ','しかも','さらに']);
  cj('standard','晴れるといわれていた。□、昼から雪がふり出した。','ところが',['だから','そして','つまり'],['前の文と反対のことが起こっています。','予想がはずれたときに使います。'],'「ところが」は、前の文から思ったこととは反対のことが起こったときに使います。',['ところが','しかし']);
  cj('standard','電車がおくれた。□、学校にちこくした。','それで',['しかし','ところが','または'],['前のことが原因になって、あとのことが起こっています。','「そのため」という意味の言葉をさがします。'],'「それで」は、前のことが原因になって、あとのことが起こるときに使います。',['それで','だから','そのため']);
  add('conjunction','standard','「雪だるまを作った。それは大きくて、りっぱだった。」の「それ」は、何をさしていますか。','雪だるま',['雪','手','朝'],['「それ」は、前の文に出てきた言葉をさしています。','大きくて、りっぱだったものは何でしょう。'],'「それ」は、前の文の「雪だるま」をさしています。',null,['ゆきだるま','雪だるま']);
  add('conjunction','standard','「ぼくは、公園でねこを見つけた。そこには、ほかにも三びきいた。」の「そこ」は、何をさしていますか。','公園',['ねこ','家','三びき'],['「そこ」は、場所をさす言葉です。','前の文に出てきた場所をさがします。'],'「そこ」は、前の文の「公園」をさしています。',null,['こうえん','公園']);
  add('conjunction','standard','「お母さんが、雪の中で転んだ。それを見て、ぼくは笑ってしまった。」の「それ」は、何をさしていますか。','お母さんが雪の中で転んだこと',['ぼくが笑ったこと','雪がふったこと','お母さんが笑ったこと'],['「それ」は、「見た」ものです。','前の文の内容を、ひとまとまりでさしています。'],'「それ」は、前の文の「お母さんが雪の中で転んだこと」をさしています。');
  add('conjunction','standard','「だから」は、前の文が何になって、あとの文のことが起こることを表しますか。','理由',['反対','例','話題の変化'],['「だから」の前の文を思い出しましょう。','「原因」ともいいます。'],'「だから」は、前の文が理由になって、あとの文のことが起こることを表します。',null,['りゆう','理由','原因']);
  add('conjunction','standard','「しかし」「ところが」「けれども」は、どんなはたらきをする言葉ですか。','前とあとが反対の内容になるようにつなぐ',['前の理由をあとで言う','前のことをまとめる','話題を変える'],['三つの言葉に、共通するはたらきを考えます。','前の文から思ったこととは、反対のことが続きます。'],'「しかし」「ところが」「けれども」は、前の文とあとの文が反対の内容になるようにつなぐ言葉です。');

  add('conjunction','advanced','「つまり」は、どんなはたらきをする言葉ですか。','前のことを言いかえたり、まとめたりする',['反対のことを言う','理由を言う','話題を変える'],['「つまり」のあとには、どんなことが続きますか。','「言いかえれば」と同じ意味です。'],'「つまり」は、前に言ったことを、言いかえたり、まとめたりするときに使います。');
  add('conjunction','advanced','「ところで」は、どんなはたらきをする言葉ですか。','話題を変える',['理由を言う','まとめる','例をあげる'],['「ところで」のあとには、前とはちがう話が続きます。','話の流れを変えるときに使います。'],'「ところで」は、話題を変えるときに使います。');
  add('conjunction','advanced','「なぜなら」は、どんなはたらきをする言葉ですか。','あとに、前のことの理由が続く',['あとに、反対のことが続く','あとに、まとめが続く','あとに、例が続く'],['「なぜなら」のあとの文は、どんな文末で終わりますか。','「～からだ」で終わることが多いです。'],'「なぜなら」は、前のことの理由を、あとで言うときに使います。');
  add('conjunction','advanced','「たとえば」は、どんなはたらきをする言葉ですか。','前のことの、具体的な例をあげる',['前のことをまとめる','反対のことを言う','理由を言う'],['「たとえば」のあとには、具体的なものが続きます。','「例をあげると」と同じ意味です。'],'「たとえば」は、前に言ったことの、具体的な例をあげるときに使います。');
  cj('advanced','雪が少ない。□、スキー場は休みになっている。','そのため',['ところが','または','つまり'],['前のことが原因で、あとのことが起こっています。','「それが原因で」という意味の言葉をさがします。'],'「そのため」は、前のことが原因になって、あとのことが起こるときに使います。',['そのため','だから','それで']);
  cj('advanced','雪が少ないと、スキー場がこまる。□、雪がふってほしいと思っている。','だから',['なぜなら','しかし','たとえば'],['前の文が理由になっています。','雪が少ないとこまるので、どう思うでしょう。'],'「だから」は、前のことが理由になって、あとのことが起こるときに使います。',['だから','そのため','それで']);
  add('conjunction','advanced','「雪のけっしょうは、六角形の形をしている。この形は、水のつぶがこおるときにできる。」の「この形」は、何をさしていますか。','六角形の形',['水のつぶ','けっしょう','こおること'],['「この」は、前の文の内容をさしています。','「この形」と言っているので、何かの形をさしています。'],'「この形」は、前の文の「六角形の形」をさしています。');
  add('conjunction','advanced','「ぼくは雪かきをした。そのあと、お母さんがお茶を入れてくれた。」の「そのあと」は、何のあとですか。','雪かきをしたあと',['お茶を入れたあと','お母さんが帰ったあと','朝になったあと'],['「その」は、前の文の内容をさしています。','前の文では、何をしましたか。'],'「そのあと」は、「ぼくが雪かきをしたあと」という意味です。');

  // ---- 物語文の読み取り：基礎8・標準12・発展8。短い文章を読んで答える。同じ文章の問いには、あとで絵を付けてもよい ----
  function st(diff,passage,ask,answer,wrong,hints,explanation,inp){
    add('story',diff,'次の文章を読んで、問いに答えましょう。\n\n'+passage+'\n\n問い：'+ask,answer,wrong,hints,explanation,null,inp||null);
  }
  var P1='朝、さくらは、まっ白な雪の道を、ゆっくりと歩いていた。ふみしめるたびに、きゅっきゅっと音がする。ふと見ると、道のはしで、小さな男の子がしゃがみこんでいた。「どうしたの。」と声をかけると、男の子は、かたくにぎった手を見せた。中には、冷たくなった小鳥がいた。さくらは、そっと自分の手ぶくろをぬいで、小鳥をつつんだ。';
  st('basic',P1,'さくらが歩いていたのは、どんな道ですか。','まっ白な雪の道',['こおった川の上','ぬかるんだ土の道','かわいた石だたみ'],['文章のはじめの文に注目します。','道のようすが書かれています。'],'「まっ白な雪の道を、ゆっくりと歩いていた」と書かれています。');
  st('basic',P1,'男の子は、手の中に何をにぎっていましたか。','小鳥',['ねこ','雪玉','手ぶくろ'],['「男の子は、かたくにぎった手を見せた」のあとに注目します。','冷たくなっていたものです。'],'男の子の手の中には、冷たくなった小鳥がいました。',['ことり','小鳥']);
  st('standard',P1,'「そっと自分の手ぶくろをぬいで」から、さくらのどんな気持ちがわかりますか。','小鳥をあたためてあげたい、というやさしい気持ち',['早く学校に行きたい','男の子をおどろかせたい','手ぶくろがいらなくなった'],['手ぶくろは、何のためにぬいだのでしょう。','「そっと」から、気づかいがわかります。'],'冷たくなった小鳥を、手ぶくろでつつんであげているので、あたためてあげたいというやさしい気持ちがわかります。');
  st('advanced',P1,'この場面のあと、さくらはどうすると考えられますか。','小鳥をあたためて、男の子といっしょに助けようとする',['小鳥を雪の中にもどす','気づかないふりをして、学校へ行く','男の子をしかる'],['さくらは、小鳥を手ぶくろでつつんでいます。','さくらは、どんな人でしょう。'],'さくらは、小鳥をつつんであげているので、このあとも、男の子といっしょに助けようとすると考えられます。');
  var P2='ふぶきの夜、ゆうたは、おじいさんと二人で、家にいた。まどの外では、風がごうごうとうなっている。「こわいよ。」と言うと、おじいさんは、だまって、ストーブにまきを足した。それから、あたたかいミルクを入れてくれた。ひと口のむと、体のしんから、ほっとした。ゆうたは、いつの間にか、風の音が気にならなくなっていた。';
  st('basic',P2,'ふぶきの夜、ゆうたは、だれと家にいましたか。','おじいさん',['お母さん','友だち','先生'],['文章のはじめの文に注目します。','「二人で」と書かれています。'],'「ゆうたは、おじいさんと二人で、家にいた」と書かれています。',['おじいさん','おじいちゃん']);
  st('standard',P2,'おじいさんは、ゆうたが「こわいよ」と言ったとき、まずどうしましたか。','だまって、ストーブにまきを足した',['「だいじょうぶ」と何度も言った','まどをあけて外を見た','ゆうたをだきしめた'],['「こわいよ。」と言ったあとの文に注目します。','おじいさんは、言葉で答えたでしょうか。'],'「おじいさんは、だまって、ストーブにまきを足した」と書かれています。');
  st('advanced',P2,'「風の音が気にならなくなっていた」のは、なぜだと考えられますか。','あたたかいミルクをのんで、安心したから',['風がやんだから','ねむってしまったから','おじいさんがおこったから'],['ミルクをのんだあとの気持ちに注目します。','「体のしんから、ほっとした」と書かれています。'],'あたたかいミルクをのんで、「体のしんから、ほっとした」ので、風の音が気にならなくなったと考えられます。');
  st('advanced',P2,'おじいさんは、どんな人だと考えられますか。','言葉よりも、行動でやさしさを見せる人',['大きな声でしかる人','いつもおしゃべりな人','いそがしくて、孫にかまわない人'],['おじいさんは、「こわいよ」と言われて、何をしましたか。','言葉ではなく、何で気づかいを見せていますか。'],'おじいさんは、だまってストーブにまきを足し、ミルクを入れてくれました。言葉よりも行動でやさしさを見せる人だと考えられます。');
  var P3='スキー教室の最後の日、けんたは、中級コースに行くかどうか、まよっていた。坂は急で、下を見ると足がすくむ。「ぼくには、むりだよ。」とつぶやくと、先生は、にっこり笑って言った。「むりかどうかは、すべってから決めよう。」けんたは、大きく息をすいこんで、雪をけった。風が、顔にあたる。ころびそうになりながらも、さいごまで、すべりきった。';
  st('basic',P3,'けんたが、まよっていたのは、何ですか。','中級コースに行くかどうか',['スキーをやめるかどうか','先生に話しかけるかどうか','帰るかどうか'],['文章のはじめの文に注目します。','何を「まよっていた」と書かれていますか。'],'「中級コースに行くかどうか、まよっていた」と書かれています。');
  st('standard',P3,'「足がすくむ」とは、どんな気持ちを表していますか。','こわくて、動けなくなる気持ち',['楽しくて、はしゃぐ気持ち','つかれて、ねむい気持ち','おこっている気持ち'],['坂が急で、下を見たときの気持ちです。','「ぼくには、むりだよ。」と言っています。'],'「足がすくむ」は、こわくて足が動かなくなるようすを表しています。');
  st('standard',P3,'先生が「むりかどうかは、すべってから決めよう」と言ったのは、どんなことを伝えたかったからですか。','やってみる前に、あきらめなくてもよいということ',['けんたはへただということ','コースを変えるべきだということ','もう時間がないということ'],['先生は、「にっこり笑って」言っています。','けんたは、やる前から「むり」と言っています。'],'先生は、やってみる前にあきらめなくてもよいということを、やさしく伝えようとしています。');
  st('advanced',P3,'さいごに、けんたはどんな気持ちになったと考えられますか。','こわさをこえて、やりとげたという満足感',['おこられて、くやしい気持ち','ほかの人にまけて、はずかしい気持ち','ころんだことを、後かいする気持ち'],['「さいごまで、すべりきった」と書かれています。','はじめの「足がすくむ」気持ちとくらべます。'],'さいごまですべりきったので、こわさをこえてやりとげたという満足感を、感じていると考えられます。');
  var P4='昼休み、みつきは、あやのと、言い合いになった。ささいなことだった。それなのに、あやのは、そのまま、そっぽをむいて、教室を出て行った。みつきは、むねの中が、もやもやした。五時間目が終わるころ、つくえの中に、小さな紙が入っているのに気づいた。「さっきは、ごめん。」と書いてあった。みつきは、思わず、あやのの方を見た。あやのは、てれくさそうに、下を向いていた。';
  st('basic',P4,'あやのは、言い合いのあと、どうしましたか。','そっぽをむいて、教室を出て行った',['すぐにあやまった','みつきをなぐさめた','先生に言いつけた'],['言い合いのあとの文に注目します。','「それなのに」のあとに書かれています。'],'「あやのは、そのまま、そっぽをむいて、教室を出て行った」と書かれています。');
  st('standard',P4,'「むねの中が、もやもやした」とは、どんな気持ちですか。','すっきりしない、いやな気持ち',['うれしくて、たまらない気持ち','つかれて、ねむい気持ち','自まんしたい気持ち'],['言い合いのあとの気持ちです。','「もやもや」は、はっきりしないようすを表しています。'],'「もやもやした」は、言い合いのあとで、すっきりしない、いやな気持ちを表しています。');
  st('standard',P4,'つくえの中の紙は、だれが入れたと考えられますか。','あやの',['先生','みつき','ほかの友だち'],['紙には、「さっきは、ごめん。」と書かれています。','みつきが見たとき、てれくさそうにしていたのは、だれですか。'],'みつきが紙に気づいたあと、あやのが、てれくさそうに下を向いていたので、あやのが入れたと考えられます。',['あやの']);
  st('advanced',P4,'あやのが、「てれくさそうに、下を向いていた」のは、なぜですか。','自分からあやまったことが、少しはずかしかったから',['みつきにおこっていたから','つくえの紙をなくしたから','五時間目の勉強がわからなかったから'],['あやのは、紙に何と書きましたか。','「てれくさい」は、少しはずかしい気持ちです。'],'あやのは、「さっきは、ごめん。」という紙を書いたので、自分からあやまったことが少しはずかしかったと考えられます。');
  var P5='ぼくの町の雪まつりでは、毎年、大きな雪の像を作る。今年は、ぼくたちのグループが、きょうりゅうを作ることになった。はじめは、形がととのわなくて、何度も、くずれた。「もうやめようか。」と言いかけたとき、ともえが、「あと少しだから。」と、雪をかためはじめた。ぼくは、はっとして、もう一度、スコップをにぎった。';
  st('basic',P5,'今年、ぼくたちのグループが作ることになったのは、何ですか。','きょうりゅう',['雪だるま','かまくら','ロボット'],['文章の二つ目の文に注目します。','「今年は、」のあとに書かれています。'],'「今年は、ぼくたちのグループが、きょうりゅうを作ることになった」と書かれています。',['きょうりゅう']);
  st('standard',P5,'「もうやめようか」と言いかけたのは、なぜですか。','何度も、くずれて、うまくいかなかったから',['ほかのグループが先に終わったから','雪がとけてしまったから','おなかがすいたから'],['その前の文に注目します。','形がととのわなくて、どうなりましたか。'],'「はじめは、形がととのわなくて、何度も、くずれた」ので、やめようかと思ったのです。');
  st('standard',P5,'ともえが「あと少しだから」と言って、雪をかためはじめたのは、どんな気持ちからだと考えられますか。','最後までやりとげたいという気持ち',['早く家に帰りたいという気持ち','ぼくをからかいたいという気持ち','ほかのグループにまけたくないという気持ち'],['ともえは、「あと少し」と言っています。','ともえは、あきらめずに、どうしましたか。'],'ともえは、「あと少しだから」と言って、あきらめずに雪をかためはじめたので、最後までやりとげたい気持ちだと考えられます。');
  st('advanced',P5,'「ぼくは、はっとして」とは、どんなようすですか。','ともえの言葉で、気づかされたようす',['ともえにしかられて、おこったようす','雪がとけて、あわてたようす','何もかも、いやになったようす'],['ぼくは、そのあと、どうしましたか。','「はっとする」は、急に気づくことです。'],'「はっとして」は、ともえの言葉で、あきらめかけていたことに気づいたようすを表しています。');
  var P6='四月、ぼくのクラスに、転校生がやってきた。南の島から来たという、はるかだ。はるかは、雪を見るのが、はじめてらしい。休み時間、窓の外を、ずっとながめている。「さわってみる？」とさそうと、目をかがやかせて、うなずいた。校庭に出ると、はるかは、そっと雪をすくって、ほおにあてた。「つめたい！」と言って、ふしぎそうに、笑った。';
  st('basic',P6,'はるかは、どこから来た転校生ですか。','南の島',['北の国','山の中の村','外国の大きな町'],['文章の二つ目の文に注目します。','「から来たという」の前に書かれています。'],'「南の島から来たという、はるかだ」と書かれています。');
  st('standard',P6,'はるかが、窓の外を、ずっとながめていたのは、なぜですか。','雪を見るのが、はじめてだったから',['外にいる友だちをさがしていたから','先生にしかられたから','雪がきらいだったから'],['そのひとつ前の文に注目します。','はるかは、南の島から来ました。'],'はるかは雪を見るのがはじめてなので、心がひかれていたのです。');
  st('standard',P6,'「目をかがやかせて」から、はるかのどんな気持ちがわかりますか。','わくわくして、早くさわってみたい気持ち',['はずかしくて、にげたい気持ち','おこっている気持ち','つまらなくて、ねむい気持ち'],['「さわってみる？」と聞かれたときの反応です。','「かがやく」は、うれしさや期待を表します。'],'「目をかがやかせて」は、わくわくして、早くさわってみたいという気持ちを表しています。');
  st('advanced',P6,'さいごの「ふしぎそうに、笑った」には、どんな気持ちが表れていますか。','はじめて知る雪のつめたさに、おどろきとうれしさを感じている',['雪がいやで、がまんしている','ぼくをばかにしている','もうあきてしまった'],['はるかは、はじめて雪にさわりました。','「つめたい！」と言いながら、笑っています。'],'はじめて雪にさわって、つめたさにおどろきながらも、うれしく感じている気持ちが表れています。');
  var P7='おばあちゃんの家では、冬になると、毎朝、屋根の雪おろしをする。ぼくは、はじめて、手伝わせてもらった。はしごをのぼると、遠くの山まで、見わたせた。「どうだい。」と、おばあちゃんは、白い息をはきながら、言った。「きれいだね。」と答えると、おばあちゃんは、「だから、雪国はやめられないのさ。」と、うれしそうに笑った。';
  st('basic',P7,'ぼくが、はじめてさせてもらったのは、何ですか。','屋根の雪おろし',['雪だるま作り','山のぼり','雪道のそうじ'],['文章の二つ目の文に注目します。','「はじめて、手伝わせてもらった」と書かれています。'],'一つ目の文の「屋根の雪おろし」を、ぼくははじめて手伝わせてもらいました。');
  st('standard',P7,'はしごをのぼると、何が見わたせましたか。','遠くの山',['海','町のにぎやかな通り','おばあちゃんの畑'],['はしごをのぼったあとの文に注目します。','「遠くの」と書かれています。'],'「はしごをのぼると、遠くの山まで、見わたせた」と書かれています。');
  st('standard',P7,'おばあちゃんが「だから、雪国はやめられないのさ」と言ったのは、どんな気持ちからですか。','雪国のけしきの美しさが、好きだという気持ち',['雪おろしがつらいという気持ち','早く引っこしたいという気持ち','ぼくにおこっているという気持ち'],['「だから」の前に、ぼくが何と言ったかに注目します。','おばあちゃんは、「うれしそうに」笑っています。'],'ぼくが「きれいだね」と答えたので、おばあちゃんは、雪国のけしきの美しさが好きだという気持ちを、ぼくと分かち合えて、うれしかったのです。');
  st('advanced',P7,'おばあちゃんが、ぼくに「どうだい。」と聞いたのは、なぜだと考えられますか。','雪国のよさを、ぼくにも感じてほしかったから',['ぼくのしっぱいをしかるため','つかれて、休みたかったから','屋根の上が、あぶないから'],['「どうだい。」は、感想を聞く言葉です。','ぼくが答えたあとの、おばあちゃんの反応も手がかりです。'],'「どうだい。」は、ぼくに、雪国のよさを感じてほしくて、感想を聞いた言葉だと考えられます。');

  // ---- 説明文の読み取り：基礎8・標準12・発展8。短い説明文を読んで答える ----
  function ex(diff,passage,ask,answer,wrong,hints,explanation,inp){
    add('explain',diff,'次の文章を読んで、問いに答えましょう。\n\n'+passage+'\n\n問い：'+ask,answer,wrong,hints,explanation,null,inp||null);
  }
  var E1='雪のけっしょうの形は、空の気温やしめりぐあいによって、変わる。気温が、とても低いときには、かためで、柱のような形になることが多い。気温が、少し高いときには、えだわかれした、六角形の形になりやすい。つまり、けっしょうの形を見れば、雪が、どんな空気の中でできたかが、わかるのである。';
  ex('basic',E1,'けっしょうの形は、何によって変わりますか。','空の気温やしめりぐあい',['地面のかたさ','雪のつもった量','風のむき'],['文章のはじめの文に注目します。','「によって、変わる」と書かれています。'],'「雪のけっしょうの形は、空の気温やしめりぐあいによって、変わる」と書かれています。');
  ex('standard',E1,'気温が少し高いときには、けっしょうはどんな形になりやすいですか。','えだわかれした六角形',['柱のような形','丸い形','三角形'],['「気温が、少し高いときには、」のあとに注目します。','気温が低いときの形とは、ちがいます。'],'「気温が、少し高いときには、えだわかれした、六角形の形になりやすい」と書かれています。');
  ex('standard',E1,'「つまり」は、どんなはたらきをしていますか。','前に述べたことを、まとめるはたらき',['話題を変えるはたらき','反対のことを述べるはたらき','理由を述べるはたらき'],['「つまり」の前と後を、くらべて読みましょう。','あとの文は、前の二つの文の内容をまとめています。'],'「つまり」は、前に述べたことをまとめるときに使います。');
  ex('advanced',E1,'この文章からわかることは、何ですか。','けっしょうの形から、雪ができた空のようすがわかる',['雪のけっしょうは、どれも同じ形をしている','気温が低いほど、六角形になる','雪は、地面でけっしょうになる'],['文章のさいごの文に注目します。','けっしょうの形と、空の様子の関係が書かれています。'],'さいごの文に、「けっしょうの形を見れば、雪が、どんな空気の中でできたかが、わかる」とまとめられています。');
  var E2='雪は、ふるときは、じゃまなものと思われがちだ。しかし、実は、雪どけ水は、わたしたちのくらしに、大切な水になっている。春になると、山にたまった雪が、少しずつとけて、川に流れこむ。この水が、田や畑をうるおし、ダムにためられて、電気や水道に使われる。雪は、「ふる貯水池」ともいえるのである。';
  ex('basic',E2,'雪どけ水は、わたしたちのくらしにとって、どんな水ですか。','大切な水',['じゃまな水','よごれた水','つめたすぎる水'],['「しかし、実は、」のあとに注目します。','前の文とは、反対のことが書かれています。'],'「雪どけ水は、わたしたちのくらしに、大切な水になっている」と書かれています。',['大切','たいせつ','大切な水','たいせつな水']);
  ex('standard',E2,'春になると、山の雪はどうなりますか。','少しずつとけて、川に流れこむ',['すべて地面にしみこむ','空にのぼって雲になる','海まで一気に流れる'],['「春になると、」のあとに注目します。','雪がとけた水の行き先が書かれています。'],'「春になると、山にたまった雪が、少しずつとけて、川に流れこむ」と書かれています。');
  ex('standard',E2,'雪どけ水は、どんなことに使われていますか。','田や畑をうるおし、電気や水道に使われる',['雪まつりの雪を作る','雪かきの道具になる','ぜんぶ海にすてられる'],['「この水が、」のあとに注目します。','田や畑のほかにも、書かれています。'],'「この水が、田や畑をうるおし、ダムにためられて、電気や水道に使われる」と書かれています。');
  ex('advanced',E2,'「ふる貯水池」とは、どういう意味ですか。','雪が、水をためておいてくれる池のはたらきをしているということ',['雪が、池の水をこおらせること','雪が、水を空にもどすこと','雪が、水をよごすということ'],['「貯水池」は、水をためておく池のことです。','雪が、春まで水をためておいてくれることをたとえています。'],'雪は、冬の間に水をためておき、春にとけて水をくれるので、「ふる貯水池」とたとえられています。');
  var E3='ユキウサギは、冬になると、毛が白くなる。雪の中では、白い毛は、てきから身をかくすのに役立つ。春になると、毛は、茶色にもどる。これを、「毛がわり」という。毛がわりは、日の光が当たる長さが変わることが、きっかけになっている。';
  ex('basic',E3,'ユキウサギの毛は、冬になると、何色になりますか。','白',['茶色','黒','赤'],['文章のはじめの文に注目します。','冬の毛の色が書かれています。'],'「ユキウサギは、冬になると、毛が白くなる」と書かれています。',['白','しろ','白い']);
  ex('basic',E3,'白い毛は、冬にどんな役に立ちますか。','雪の中で、てきから身をかくす',['体をあたためる','えさを見つける','かけっこが速くなる'],['文章の二つ目の文に注目します。','雪の中で、白い毛はどうなるでしょう。'],'「雪の中では、白い毛は、てきから身をかくすのに役立つ」と書かれています。');
  ex('standard',E3,'毛の色が変わることを、何といいますか。','毛がわり',['冬みん','だっぴ','毛づくろい'],['「これを、」のあとに注目します。','「かぎ」でかこまれた言葉です。'],'「これを、『毛がわり』という」と書かれています。',['けがわり','毛がわり']);
  ex('advanced',E3,'毛がわりのきっかけは、何ですか。','日の光が当たる長さが変わること',['気温だけが変わること','えさが少なくなること','てきがふえること'],['文章のさいごの文に注目します。','「きっかけになっている」と書かれています。'],'「毛がわりは、日の光が当たる長さが変わることが、きっかけになっている」と書かれています。');
  var E4='つららは、屋根の雪が、とけて、できる。昼間、日光であたたまった屋根の雪が、とけて、水になる。その水は、屋根のはしに流れ、夜の冷たい空気で、こおる。これを、くり返すうちに、水は、少しずつこおって、長くのびていく。気温が、一日中、0度より低いときには、できにくい。';
  ex('basic',E4,'つららは、どこにできますか。','屋根のはし',['地面','木のみき','雪だるま'],['文章の三つ目の文に注目します。','水が流れて行く先です。'],'屋根の雪がとけた水は、屋根のはしに流れて、こおります。');
  ex('standard',E4,'屋根の雪がとけるのは、なぜですか。','昼間、日光であたためられるから',['夜の空気があたたかいから','雨がふるから','雪かきをするから'],['文章の二つ目の文に注目します。','「昼間、」のあとに書かれています。'],'「昼間、日光であたたまった屋根の雪が、とけて、水になる」と書かれています。');
  ex('advanced',E4,'水がこおるのは、いつですか。','夜の冷たい空気にふれたとき',['日光が当たったとき','昼間の風にふれたとき','雪がふっているとき'],['文章の三つ目の文に注目します。','「夜の冷たい空気で、こおる」と書かれています。'],'「夜の冷たい空気で、こおる」と書かれています。');
  ex('advanced',E4,'つららができにくいのは、どんなときですか。','一日中、気温が0度より低いとき',['昼間、あたたかいとき','雪がたくさんふったとき','屋根がきれいなとき'],['文章のさいごの文に注目します。','屋根の雪が、とけるかどうかを考えます。'],'「気温が、一日中、0度より低いときには、できにくい」と書かれています。屋根の雪がとけないからです。');
  var E5='雪の下では、植物は、あんがい、あたたかくすごしている。雪は、空気を多くふくむので、熱を伝えにくい。そのため、地面が、外の冷たい空気に、さらされるのを、ふせいでくれる。雪が、ふとんのような、役目をはたしているのだ。だから、雪の多い土地ほど、冬の間も、地面がこおりにくい。';
  ex('basic',E5,'雪の下では、植物はどうすごしていますか。','あんがい、あたたかくすごしている',['こおってしまう','すぐにかれる','光をあびてのびる'],['文章のはじめの文に注目します。','「あんがい」のあとに書かれています。'],'「雪の下では、植物は、あんがい、あたたかくすごしている」と書かれています。');
  ex('standard',E5,'雪が熱を伝えにくいのは、なぜですか。','空気を多くふくんでいるから',['雪が白いから','雪がやわらかいから','雪の下に水があるから'],['文章の二つ目の文に注目します。','「ので」の前に、理由が書かれています。'],'「雪は、空気を多くふくむので、熱を伝えにくい」と書かれています。');
  ex('standard',E5,'「そのため」のあとには、何が書かれていますか。','雪が、地面を冷たい空気からふせぐこと',['雪が空気をふくむこと','雪が白いこと','地面がこおること'],['「そのため」のあとの文を、読み直しましょう。','前の文の結果が、書かれています。'],'「そのため、地面が、外の冷たい空気に、さらされるのを、ふせいでくれる」と書かれています。');
  ex('advanced',E5,'「雪が、ふとんのような役目」とは、どういうことですか。','地面を、外の冷たい空気から守ってくれること',['雪が、あたたかいものをとかすこと','雪の上で、ねむれること','雪が、重くておしつぶすこと'],['ふとんは、何のために使いますか。','「そのため」の文に、内容が書かれています。'],'ふとんが体をあたためるように、雪が、地面を冷たい空気から守る役目をしている、ということです。');
  var E6='雪の多い地方の家には、いろいろなくふうがある。屋根は、雪がすべり落ちやすいよう、急なかたむきになっている。げんかんは、雪にうまらないよう、高い場所に作られている。また、雪で道がふさがれないよう、家のまわりに、雪をとかす水が流れる、みぞを作る町もある。どれも、雪とつき合っていくための、知えである。';
  ex('basic',E6,'雪の多い地方の家の屋根は、どんな形になっていますか。','急なかたむき',['平ら','丸い形','ひくい山の形'],['文章の二つ目の文に注目します。','「雪がすべり落ちやすいよう」と書かれています。'],'「屋根は、雪がすべり落ちやすいよう、急なかたむきになっている」と書かれています。');
  ex('standard',E6,'げんかんが高い場所に作られているのは、なぜですか。','雪にうまらないようにするため',['景色を見やすくするため','風を通すため','屋根を高く見せるため'],['文章の三つ目の文に注目します。','「よう」の前に、理由が書かれています。'],'「げんかんは、雪にうまらないよう、高い場所に作られている」と書かれています。');
  ex('standard',E6,'「みぞ」には、どんな役目がありますか。','雪をとかす水を流して、道がふさがれないようにする',['雨水をためる','ごみを集める','雪を高くつみ上げる'],['「また、」のあとの文に注目します。','道がふさがれないように、何をするのでしょう。'],'「雪で道がふさがれないよう、家のまわりに、雪をとかす水が流れる、みぞを作る町もある」と書かれています。');
  ex('advanced',E6,'「どれも、雪とつき合っていくための、知えである」とありますが、何についてのまとめですか。','雪の多い地方の家や町のくふう',['雪のけっしょうの形','雪が水になるようす','雪かきの道具の種類'],['「どれも」は、前の文までの内容をさしています。','屋根・げんかん・みぞの三つに共通することは何でしょう。'],'「どれも」は、屋根・げんかん・みぞなど、雪の多い地方の家や町のくふうをさしています。');
  var E7='雪がふった朝は、あたりが、しずかに感じられる。これは、気のせいではない。雪には、小さなすきまが、たくさんあり、音を、すいこむ性質がある。そのため、車の音や、人の声が、雪にすいこまれて、遠くまでとどきにくくなる。しずかさの正体は、雪のすきまなのだ。';
  ex('basic',E7,'雪がふった朝は、あたりが、どう感じられますか。','しずかに感じられる',['にぎやかに感じられる','明るく感じられる','あたたかく感じられる'],['文章のはじめの文に注目します。','「感じられる」の前の言葉です。'],'「雪がふった朝は、あたりが、しずかに感じられる」と書かれています。');
  ex('standard',E7,'雪には、どんな性質がありますか。','音をすいこむ性質',['音を大きくする性質','音を高くする性質','音をひびかせる性質'],['文章の三つ目の文に注目します。','「小さなすきまが、たくさんあり」のあとに書かれています。'],'「雪には、小さなすきまが、たくさんあり、音を、すいこむ性質がある」と書かれています。');
  ex('standard',E7,'「しずかさの正体は、雪のすきまなのだ」とは、どういうことですか。','雪のすきまが音をすいこむので、しずかになるということ',['雪がふると、音を出す人がいなくなるということ','雪のすきまから、小さな音がもれるということ','雪が、音をすべて消してしまうということ'],['「正体」は、ほんとうのすがたのことです。','音をすいこむのは、雪のどの部分でしょう。'],'しずかになる理由は、雪の小さなすきまが、音をすいこむからだ、ということです。');
  ex('advanced',E7,'この文章の組み立てとして、正しいものはどれですか。','はじめに現象をのべ、次に理由を説明し、さいごにまとめている',['はじめに結論を言い、体験を話している','質問と答えをくり返している','自分の考えを三つならべている'],['はじめの文は、雪がふった朝のようすです。','さいごの文は、「しずかさの正体は」と、まとめています。'],'この文章は、はじめに雪の朝のようすをのべ、次に理由を説明し、さいごに「しずかさの正体は、雪のすきま」とまとめています。');
